    // Auto-paginate if content doesn't fill the viewport (initial fill)
    if (
      contentHeight > 0 &&
      contentHeight < (flashListRef.current?.recyclerlistview_unsafe?.getRenderedSize()?.height ?? Number.MAX_SAFE_INTEGER) &&
      !isPaginatingRef.current &&
